/* ===================== BÀI 22 · Nút nhấn và chống dội ===================== */
/* Bài 22 · Nút nhấn và chống dội (AMTS-EMB-001-M06-L02, MC51-022) — sinh bởi tools/author/mcu8051/l22.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const PR22=[{"label":"Ví dụ: LED sáng khi K1 đang bấm","code":"; Ví dụ 1: LED P1.0 sáng nếu K1 đang bấm lúc đọc\n; Giữ K1 (P3.2) rồi bấm Từng bước; nhả ra rồi chạy lại.\n        ORG     0000H\n        JB      P3.2,XONG               ; chân = 1: K1 nhả, bỏ qua\n        CLR     P1.0                    ; chân = 0: K1 bấm, bật LED\nXONG:   SJMP    $\n        END\n","note":"Không bấm: JB nhảy tới XONG, LED tắt, 2 chu kỳ. Giữ K1 rồi chạy lại: JB không nhảy, CLR P1.0 bật LED, 3 chu kỳ. Chương trình chỉ đọc nút một lần — bấm sau lúc đó không có tác dụng.","dev":{"led":true,"btn":true},"fosc":12000000},{"label":"Lỗi: Đếm sườn khi nút còn dội","code":"; Lỗi 2: đếm sườn xuống của K1, không chống dội\n; 200 mẫu, mỗi mẫu 9 chu kỳ. Nút dội: một lần bấm đếm nhiều.\n        ORG     0000H\n        MOV     R5,#00H                 ; số lần nhấn đếm được\n        MOV     R4,#0FFH                ; lịch sử mẫu (1 = nhả)\n        MOV     R7,#200                 ; 200 mẫu\nLAP:    MOV     C,P3.2                  ; mẫu mới của K1\n        MOV     A,R4\n        RLC     A                       ; đẩy mẫu mới vào bit 0\n        MOV     R4,A\n        ANL     A,#03H                  ; hai mẫu gần nhất\n        CJNE    A,#02H,KHONG            ; 10B: trước 1, nay 0 = sườn\n        INC     R5\nKHONG:  DJNZ    R7,LAP\n        SJMP    $\n        END\n","note":"Đổi Tốc độ sang Nhanh, bấm Chạy rồi bấm K1 một lần: R5 tăng 3 (mỗi lần nảy xuống 0 là một sườn). Đoán trước: không bấm gì thì R5 và R4 cuối bằng bao nhiêu? (00H và FFH, 1 803 chu kỳ.)","dev":{"led":true,"btn":{"bounce":[100,300,600,1000]}},"fosc":12000000,"speed":"real"},{"label":"Ví dụ: Chống dội kiểu chờ (blocking)","code":"; Ví dụ 3: chống dội kiểu chờ (blocking), trễ khoảng 10 ms\n; CPU đứng chờ ở CHO và NHA: không làm được việc gì khác.\n        ORG     0000H\nCHO:    JB      P3.2,CHO                ; chờ K1 xuống 0\n        MOV     R7,#20                  ; trễ 20 x 503 + 1 = 10061 CK\nTRE:    MOV     R6,#250\n        DJNZ    R6,$                    ; 250 x 2 = 500 chu kỳ\n        DJNZ    R7,TRE\n        JB      P3.2,CHO                ; hết dội mà đã nhả: nhiễu\n        CPL     P1.0                    ; một lần nhấn thật: đổi LED\nNHA:    JNB     P3.2,NHA                ; chờ thả nút\n        SJMP    $\n        END\n","note":"Bấm Chạy, bấm và giữ K1: sau khoảng 10 ms LED P1.0 đổi đúng một lần dù chân còn dội; nhả K1 thì chương trình tới SJMP $. Trong lúc chờ, CPU không làm gì khác.","dev":{"led":true,"btn":{"bounce":[100,300,600,1000]}},"fosc":12000000,"speed":"real"},{"label":"Ví dụ: Bộ lọc theo thời gian (4 mẫu)","code":"; Ví dụ 4: bộ lọc theo thời gian - đủ 4 mẫu khác mới đổi\n; Mẫu cách nhau ~0,5 ms; R3 = trạng thái ổn định (04H nhả).\n        ORG     0000H\n        MOV     R5,#00H                 ; số sự kiện nhấn\n        MOV     R3,#04H                 ; trạng thái ổn định: nhả\n        MOV     R2,#4                   ; còn cần 4 mẫu khác liên tiếp\n        MOV     R7,#40                  ; 40 mẫu (khoảng 20 ms)\nLAP:    MOV     R6,#245\n        DJNZ    R6,$                    ; chờ tới lần lấy mẫu sau\n        MOV     A,P3\n        ANL     A,#04H                  ; mẫu K1: 04H nhả, 00H bấm\n        XRL     A,R3                    ; 0 = giống trạng thái ổn định\n        JZ      GIONG\n        DJNZ    R2,TIEP                 ; khác: đếm, chưa đủ 4 thì thôi\n        MOV     A,R3\n        XRL     A,#04H                  ; đủ 4 mẫu: đổi trạng thái\n        MOV     R3,A\n        JNZ     GIONG                   ; vừa thành \"nhả\": không đếm\n        INC     R5                      ; vừa thành \"bấm\": 1 sự kiện\nGIONG:  MOV     R2,#4                   ; nạp lại bộ đếm mẫu\nTIEP:   DJNZ    R7,LAP\n        SJMP    $\n        END\n","note":"Đổi Tốc độ sang Nhanh, chạy rồi bấm K1: R5 chỉ tăng 1 dù dội, sau khi đủ 4 mẫu bấm liên tiếp (R2 đếm ngược 4 → 0). Không bấm: 19 964 chu kỳ, R5 = 00H, R3 = 04H.","dev":{"led":true,"btn":{"bounce":[100,300,600,1000]}},"fosc":12000000,"speed":"real"},{"label":"Bẫy: Đếm theo mức khi giữ nút","code":"; Bẫy 5: đếm theo MỨC - giữ nút bao lâu đếm bấy nhiêu\n; 40 mẫu cách nhau 495 chu kỳ; giữ K1 khoảng 5 ms.\n        ORG     0000H\n        MOV     R5,#00H                 ; số \"lần nhấn\"\n        MOV     R7,#40\nLAP:    MOV     R6,#245\n        DJNZ    R6,$                    ; chờ tới lần lấy mẫu sau\n        JB      P3.2,TIEP               ; nhả: bỏ qua\n        INC     R5                      ; đang bấm: đếm (sai!)\nTIEP:   DJNZ    R7,LAP\n        SJMP    $\n        END\n","note":"Đổi Tốc độ sang Nhanh, chạy rồi giữ K1 vài giây thực: R5 tăng mỗi lần lấy mẫu. Kịch bản kiểm chứng: giữ từ 5 ms tới 10 ms → R5 = 0AH (10 lần) cho một lần bấm.","dev":{"led":true,"btn":true},"fosc":12000000,"speed":"real"}];
const sim22=makeSim51(document.getElementById("m51-l22"),{id:"s22",presets:PR22,ram:256});
makeEx51(document.getElementById("ex-l22"),"l22",[{"t":"Cờ nút K2 và LED báo","d":"<p>Nút K2 nối chân <code>P3.3<\/code> xuống GND (bấm = chân 0). Đọc K2 <b>một lần<\/b>: ghi vào ô <code>30H<\/code> giá trị <code>01H<\/code> nếu K2 đang bấm, <code>00H<\/code> nếu đang nhả (ô 30H có thể đang chứa rác); đồng thời cho LED <code>P1.1<\/code> (sáng khi chân = 0) sáng đúng khi K2 bấm. Các bit chốt khác của P1 giữ 1. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: chân P3 = <code>F7H<\/code> (K2 bấm) → <code>30H = 01H<\/code>, chốt <code>P1 = FDH<\/code>.<\/p>","start":"        ORG     0000H\n        MOV     C,P3.3                  ; mức chân K2\n        MOV     P1.1,C                  ; LED đi theo chân\n        CLR     A\n        RLC     A                       ; A = mức chân K2\n        MOV     30H,A\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"pins":{"P3":247}},"expect":{"iram":{"0x30":1},"ports":{"P1":253}}},{"setup":{"pins":{"P3":255}},"expect":{"iram":{"0x30":0},"ports":{"P1":255}}},{"setup":{"pins":{"P3":251}},"expect":{"iram":{"0x30":0},"ports":{"P1":255}}},{"setup":{"pins":{"P3":243}},"expect":{"iram":{"0x30":1},"ports":{"P1":253}}},{"setup":{"pins":{"P3":0}},"expect":{"iram":{"0x30":1},"ports":{"P1":253}}},{"setup":{"pins":{"P3":255},"iram":{"0x30":85}},"expect":{"iram":{"0x30":0},"ports":{"P1":255}}}]},"hints":["Đọc chân K2 vào cờ C một lần, dùng lại cho cả hai việc.","Chép thẳng C ra chân LED: K2 bấm (C = 0) thì LED P1.1 cũng nhận 0 và sáng.","Cờ cần theo nghĩa bấm = 1, trong khi C đang là mức chân: đảo C rồi đưa C vào bit 0 của một byte đã xóa."],"why":"Đọc chân một lần rồi dùng giá trị đó cho mọi việc, tránh trường hợp hai lần đọc cho hai kết quả khác nhau khi nút đang dội. LED và nút cùng tích cực mức thấp nên chép C thẳng ra P1.1; cờ logic thì phải đảo."},{"t":"Một bước bộ lọc chống dội","d":"<p>Bộ lọc của ví dụ 4 viết thành một bước gọi đều đặn (sau này do timer gọi). Trạng thái lưu trong RAM: <code>30H<\/code> = trạng thái ổn định của K1 (<code>01H<\/code> đang bấm, <code>00H<\/code> đang nhả), <code>31H<\/code> = số mẫu liên tiếp khác trạng thái ổn định (0–3). Mẫu mới m = 1 nếu chân <code>P3.2<\/code> = 0. Viết một bước: nếu m bằng trạng thái ổn định thì <code>31H = 00H<\/code>; ngược lại tăng <code>31H<\/code>, khi đủ 4 thì <code>30H = m<\/code>, <code>31H = 00H<\/code>. Ô <code>32H<\/code> = <code>01H<\/code> đúng ở bước trạng thái vừa đổi sang “bấm” (sự kiện nhấn), mọi trường hợp khác <code>00H<\/code>. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>30H = 00H<\/code>, <code>31H = 02H<\/code>, K1 bấm → <code>31H = 03H<\/code>, <code>30H = 00H<\/code>, <code>32H = 00H<\/code>.<\/p>","start":"        ORG     0000H\n        MOV     C,P3.2\n        CPL     C                       ; C = 1 khi bấm\n        CLR     A\n        RLC     A                       ; A = mẫu mới\n        MOV     30H,A                   ; nhận ngay mẫu mới (không lọc)\n        MOV     31H,#00H\n        MOV     32H,A                   ; báo nhấn mỗi khi đang bấm\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":0,"0x31":2,"0x32":85},"pins":{"P3":251}},"expect":{"iram":{"0x30":0,"0x31":3,"0x32":0}}},{"setup":{"iram":{"0x30":0,"0x31":0,"0x32":85},"pins":{"P3":255}},"expect":{"iram":{"0x30":0,"0x31":0,"0x32":0}}},{"setup":{"iram":{"0x30":0,"0x31":3,"0x32":85},"pins":{"P3":251}},"expect":{"iram":{"0x30":1,"0x31":0,"0x32":1}}},{"setup":{"iram":{"0x30":1,"0x31":3,"0x32":85},"pins":{"P3":255}},"expect":{"iram":{"0x30":0,"0x31":0,"0x32":0}}},{"setup":{"iram":{"0x30":1,"0x31":2,"0x32":85},"pins":{"P3":251}},"expect":{"iram":{"0x30":1,"0x31":0,"0x32":0}}},{"setup":{"iram":{"0x30":0,"0x31":3,"0x32":85},"pins":{"P3":255}},"expect":{"iram":{"0x30":0,"0x31":0,"0x32":0}}},{"setup":{"iram":{"0x30":1,"0x31":0,"0x32":85},"pins":{"P3":255}},"expect":{"iram":{"0x30":1,"0x31":1,"0x32":0}}}]},"hints":["Ghi 32H = 00H ngay đầu chương trình; chỉ một nhánh ghi 01H.","Tạo m trong A: đọc P3.2 vào C, đảo C, xóa A, xoay C vào A. XRL A với 30H cho 0 khi giống trạng thái ổn định.","Nhánh “khác trạng thái ổn định”: tăng bộ đếm rồi so với 4; khi đủ, trạng thái mới là trạng thái cũ đảo bit 0."],"why":"Bộ lọc chỉ đổi trạng thái khi chân khác trạng thái ổn định đủ 4 mẫu liên tiếp, nên dội ngắn hơn 4 chu kỳ lấy mẫu bị bỏ qua. Sự kiện nhấn sinh ra đúng một lần ở bước trạng thái đổi sang “bấm”; giữ nút lâu không sinh thêm sự kiện. Code mẫu chép mẫu mới thẳng vào trạng thái — không lọc gì."},{"t":"Sự kiện nhấn/thả 4 nút, ≤ 14 chu kỳ","d":"<p>Ô <code>30H<\/code> chứa cờ trạng thái trước của 4 nút: bit <i>i<\/i> = 1 khi K(<i>i<\/i>+1) (chân <code>P3.(i+2)<\/code>) đang bấm. Đọc P3, tính cờ mới, ghi: <code>31H<\/code> = sự kiện nhấn (bit = 1 khi nút vừa từ nhả sang bấm), <code>32H<\/code> = sự kiện thả (vừa từ bấm sang nhả), <code>30H<\/code> = cờ mới. Bit 4–7 của cả ba ô bằng 0; P3.0, P3.1, P3.6, P3.7 phải bị bỏ qua. Yêu cầu: không quá <b>14 chu kỳ máy<\/b> (tính cả một lần <code>SJMP $<\/code>) và không quá <b>22 byte<\/b>, không dùng vòng lặp hay lệnh nhảy theo từng nút.<\/p><p>Ví dụ: <code>30H = 00H<\/code>, chân P3 = <code>FBH<\/code> → <code>30H = 01H<\/code>, <code>31H = 01H<\/code>, <code>32H = 00H<\/code>. Code mẫu đúng nhưng tốn 18 chu kỳ, 24 byte.<\/p>","start":"        ORG     0000H\n        MOV     A,P3\n        CPL     A                       ; bấm = 1\n        RR      A\n        RR      A                       ; K1..K4 về bit 0..3\n        ANL     A,#0FH\n        MOV     R2,A                    ; R2 = cờ mới\n        MOV     A,30H\n        CPL     A\n        ANL     A,R2                    ; nhấn = mới AND NOT cũ\n        MOV     31H,A\n        MOV     A,R2\n        CPL     A\n        ANL     A,30H                   ; thả = cũ AND NOT mới\n        MOV     32H,A\n        MOV     30H,R2                  ; lưu cờ mới\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":0,"0x31":85,"0x32":85},"pins":{"P3":251}},"expect":{"iram":{"0x30":1,"0x31":1,"0x32":0}}},{"setup":{"iram":{"0x30":1,"0x31":85,"0x32":85},"pins":{"P3":251}},"expect":{"iram":{"0x30":1,"0x31":0,"0x32":0}}},{"setup":{"iram":{"0x30":1,"0x31":85,"0x32":85},"pins":{"P3":255}},"expect":{"iram":{"0x30":0,"0x31":0,"0x32":1}}},{"setup":{"iram":{"0x30":5,"0x31":85,"0x32":85},"pins":{"P3":195}},"expect":{"iram":{"0x30":15,"0x31":10,"0x32":0}}},{"setup":{"iram":{"0x30":15,"0x31":85,"0x32":85},"pins":{"P3":63}},"expect":{"iram":{"0x30":0,"0x31":0,"0x32":15}}},{"setup":{"iram":{"0x30":6,"0x31":85,"0x32":85},"pins":{"P3":59}},"expect":{"iram":{"0x30":1,"0x31":1,"0x32":6}}}],"maxCyc":14,"maxBytes":22},"hints":["Cờ mới tính như bài tập 1 của Bài 21. Nút “đổi” = cũ XOR mới; nhấn = đổi AND mới; thả = đổi AND cũ.","Lệnh XCH A,30H (2 byte, 1 chu kỳ) cùng lúc lấy cờ cũ ra A và cất cờ mới vào 30H — bỏ được lệnh MOV 30H,R2 (2 chu kỳ) của code mẫu.","Nhấn và thả là hai phần rời nhau của “đổi”: từ “đổi” và “nhấn” tính được “thả” chỉ bằng một phép logic."],"why":"Xử lý cả 4 nút song song bằng phép toán byte: đổi = cũ ⊕ mới, nhấn = đổi ∧ mới, thả = đổi ⊕ nhấn. Lời giải 12 lệnh 1 chu kỳ + 2 chu kỳ SJMP $ = 14 chu kỳ, 21 byte; mọi nhánh có cùng thời gian chạy — điều có ích khi bước này được gọi trong ngắt timer."}]);

makeQuiz("quiz22","score22",[{"q": "Vòng lặp đọc K1 mỗi 9 chu kỳ máy (12 MHz) và đếm sườn 1→0. Bấm một lần, chân nảy xuống 0 ba lần trong 1 ms. Bộ đếm tăng bao nhiêu?", "o": ["1", "3", "0", "Khoảng 111"], "a": 1, "e": "Mẫu cách nhau 9 µs, mỗi đoạn nảy dài hàng trăm µs nên cả ba lần chân xuống 0 đều được thấy như sườn mới. 111 là số mẫu mỗi mili giây, không phải số sườn."}, {"q": "Bộ lọc lấy mẫu mỗi 5 ms và cần 4 mẫu khác liên tiếp mới đổi trạng thái. Thời gian chống dội xấp xỉ bao nhiêu?", "o": ["5 ms", "4 ms", "20 ms", "1,25 ms"], "a": 2, "e": "Trạng thái chỉ đổi khi chân giữ mức mới suốt khoảng 4 chu kỳ lấy mẫu: 4 × 5 ms = 20 ms. Đó cũng là độ trễ phản hồi người dùng cảm nhận."}, {"q": "Nhược điểm chính của chống dội kiểu chờ (thấy 0 → trễ 10 ms → đọc lại → chờ thả) là gì?", "o": ["CPU đứng chờ, không làm được việc khác và có thể bỏ lỡ sự kiện khác", "Không lọc được dội", "Đếm mỗi lần bấm thành hai lần", "Cần ngắt timer mới chạy được"], "a": 0, "e": "Logic đúng: dội bị bỏ qua và mỗi lần nhấn chỉ được nhận một lần. Nhưng trong lúc trễ và lúc chờ thả, CPU bị chặn: không quét hiển thị, không nhận dữ liệu khác."}, {"q": "Cờ cũ của 4 nút là 05H, cờ mới là 0CH. Byte sự kiện nhấn (vừa từ nhả sang bấm) bằng bao nhiêu?", "o": ["09H", "01H", "0CH", "08H"], "a": 3, "e": "Đổi = 05H XOR 0CH = 09H; nhấn = đổi AND mới = 09H AND 0CH = 08H (nút K4). Bit 0 đổi từ 1 sang 0 là sự kiện thả (thả = 01H), không phải nhấn."}, {"q": "Vì sao chương trình “đang bấm thì cộng 1 mỗi lần lấy mẫu” sai yêu cầu đếm số lần nhấn?", "o": ["Giữ nút lâu được đếm nhiều lần; cần đếm theo sự kiện (sườn sau lọc)", "Vì nó không đọc được chân P3.2", "Vì JB đọc chốt chứ không đọc chân", "Vì INC R5 làm hỏng cờ CY"], "a": 0, "e": "Đếm theo mức cộng thêm mỗi lần lấy mẫu khi nút còn giữ (ví dụ 5: 10 lần cho một lần giữ 5 ms). JB đọc chân; INC Rn không đổi cờ CY."}]);

